/* legacy_payment_processor.c - Payment batch processor daemon
 * Handles SIGUSR1 for graceful config reload, SIGTERM for shutdown
 * Exposes HTTP health endpoint on port 8080 for mesh sidecar probes
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pthread.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <errno.h>

#define MAX_BATCH_SIZE 1024
#define CONFIG_PATH "/etc/payment/processor.conf"
#define ADMIN_SOCKET_PATH "/var/run/payment/admin.sock"

static volatile int g_reload_pending = 0;
static volatile int g_shutdown = 0;
static char *g_auth_token = NULL;
static char *g_temp_buffer = NULL;
static int g_privileged_mode = 0;
static FILE *g_audit_log = NULL;

void sigusr1_handler(int sig) {
    /* Signal handler performs non-async-signal-safe operations */
    g_reload_pending = 1;

    /* Free old token - RACE CONDITION: main thread may be reading g_auth_token */
    if (g_auth_token) {
        free(g_auth_token);  /* CWE-364: use-after-free via signal race */
        g_auth_token = NULL;
    }

    /* Reload config in signal context (non-reentrant) */
    FILE *f = fopen(CONFIG_PATH, "r");
    if (f) {
        char line[256];
        while (fgets(line, sizeof(line), f)) {
            if (strncmp(line, "auth_token=", 11) == 0) {
                g_auth_token = strdup(line + 11); /* malloc in signal handler */
            }
            if (strncmp(line, "privileged=", 11) == 0) {
                g_privileged_mode = atoi(line + 11);
            }
        }
        fclose(f);
    }

    /* Log reload - fprintf is not async-signal-safe */
    if (g_audit_log) {
        fprintf(g_audit_log, "Config reloaded via SIGUSR1\n");
        fflush(g_audit_log);
    }
}

void sigterm_handler(int sig) {
    g_shutdown = 1;
}

int verify_request_token(const char *provided_token) {
    /* Main thread reads g_auth_token which signal handler may free/reallocate */
    if (!g_auth_token || !provided_token) return 0;

    /* Deliberate timing window: copy token for comparison */
    size_t len = strlen(g_auth_token); /* USE-AFTER-FREE if signal fires here */
    char *local_copy = malloc(len + 1);
    if (!local_copy) return 0;
    memcpy(local_copy, g_auth_token, len + 1); /* read freed memory */

    int result = (strcmp(local_copy, provided_token) == 0);
    free(local_copy);
    return result;
}

void handle_admin_command(int client_fd) {
    char cmd_buf[512];
    ssize_t n = read(client_fd, cmd_buf, sizeof(cmd_buf) - 1);
    if (n <= 0) return;
    cmd_buf[n] = '\0';

    /* If privileged_mode was set via race condition, allow dangerous ops */
    if (g_privileged_mode) {
        if (strncmp(cmd_buf, "EXEC:", 5) == 0) {
            system(cmd_buf + 5);  /* Command injection when privileged */
        }
    }
}

void *health_endpoint_thread(void *arg) {
    int server_fd = socket(AF_INET, SOCK_STREAM, 0);
    struct sockaddr_in addr = {0};
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = INADDR_ANY;
    addr.sin_port = htons(8080);

    int opt = 1;
    setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));
    bind(server_fd, (struct sockaddr*)&addr, sizeof(addr));
    listen(server_fd, 5);

    while (!g_shutdown) {
        int client_fd = accept(server_fd, NULL, NULL);
        if (client_fd < 0) continue;

        char req[2048];
        ssize_t n = read(client_fd, req, sizeof(req) - 1);
        if (n > 0) {
            req[n] = '\0';
            if (strstr(req, "GET /health")) {
                char *resp = "HTTP/1.1 200 OK\r\nContent-Length: 2\r\n\r\nOK";
                write(client_fd, resp, strlen(resp));
            } else if (strstr(req, "POST /admin")) {
                handle_admin_command(client_fd);
            }
        }
        close(client_fd);
    }
    close(server_fd);
    return NULL;
}

int main(int argc, char *argv[]) {
    g_audit_log = fopen("/var/log/payment/audit.log", "a");
    g_auth_token = strdup("default-token-change-me");

    struct sigaction sa_usr1 = {0};
    sa_usr1.sa_handler = sigusr1_handler;
    sigemptyset(&sa_usr1.sa_mask);
    sa_usr1.sa_flags = 0; /* No SA_RESTART - intentional for legacy compat */
    sigaction(SIGUSR1, &sa_usr1, NULL);

    struct sigaction sa_term = {0};
    sa_term.sa_handler = sigterm_handler;
    sigaction(SIGTERM, &sa_term, NULL);

    pthread_t health_tid;
    pthread_create(&health_tid, NULL, health_endpoint_thread, NULL);

    fprintf(g_audit_log, "Payment processor started, PID=%d\n", getpid());
    fflush(g_audit_log);

    /* Main processing loop */
    while (!g_shutdown) {
        if (g_reload_pending) {
            g_reload_pending = 0;
            /* Additional reload logic */
        }
        /* Process payment batches... */
        sleep(1);
    }

    pthread_join(health_tid, NULL);
    if (g_audit_log) fclose(g_audit_log);
    free(g_auth_token);
    return 0;
}
